function parseDataUri(dataUri: string): StreamImageAttachment | null {
    const match = /^data:([^;,]+);base64,([\s\S]+)$/.exec(dataUri);
    if (!match || !match[1] || !match[2]) return null;
    return { mimeType: match[1], base64: match[2] };
