            return { valid: false, error: 'Input cannot be empty.' };
        }

        if (input.length > this.MAX_PROMPT_LENGTH) {
            return { valid: false, error: `Input exceeds maximum length of ${this.MAX_PROMPT_LENGTH} characters.` };
