        // Create an internal AbortController for timeout if specified
        const timeoutController = new AbortController();
        let timeoutId: NodeJS.Timeout | number | undefined;
        let externalAbortHandler: (() => void) | undefined;

        // ISSUE-1367: same 25s→120s raise as the non-stream path — this timer
        // covers the entire stream (queue + pre-flight + tokens), and the
        // generateContentStream callable allows 300s server-side.
        const requestTimeout = options?.timeout ?? 120_000;
        if (requestTimeout > 0) {
            timeoutId = setTimeout(() => {
                timeoutController.abort('TIMEOUT');
            }, requestTimeout);
        }

        // Combine with user signal if provided
        if (options?.signal) {
            if (options.signal.aborted) {
                timeoutController.abort(options.signal.reason || 'CANCELLED');
            } else {
                externalAbortHandler = () => timeoutController.abort(options.signal?.reason || 'CANCELLED');
                options.signal.addEventListener('abort', externalAbortHandler, { once: true });
            }
        }

        const internalSignal = timeoutController.signal;
        let costReservationId: string | undefined;
        let headers: Record<string, string> | undefined;
        const cleanupRequestLifecycle = () => {
            if (timeoutId) {
                clearTimeout(timeoutId);
                timeoutId = undefined;
            }
            if (externalAbortHandler && options?.signal) {
                options.signal.removeEventListener('abort', externalAbortHandler);
                externalAbortHandler = undefined;
            }
        };

        try {
            await this.rateLimiter.acquire(300_000, internalSignal);
            const streamResult = await this.contentBreaker.execute(async () => {
                return this.withRetry(async () => {
                    if (internalSignal.aborted) {
                        if (internalSignal.reason === 'TIMEOUT') {
                            throw new AppException(AppErrorCode.TIMEOUT, `AI Request timed out after ${requestTimeout}ms`);
                        }
                        throw new AppException(AppErrorCode.CANCELLED, 'AI Request was cancelled by user');
                    }
                    await this.ensureInitialized();

                    // 1. Explicit mock mode is not a supported runtime path.
                    if (import.meta.env.VITE_INTELLIGENCE_MOCK_MODE === 'true') {
                        throw new AppException(AppErrorCode.INTERNAL_ERROR, 'VITE_INTELLIGENCE_MOCK_MODE=true is no longer supported. Configure live intelligence services.');
                    }

                    // 2. Quota & Rate Limit (Backend)
                    const userId = auth.currentUser?.uid;
                    if (!userId) throw new AppException(AppErrorCode.UNAUTHORIZED, 'User must be authenticated for AI requests.', { retryable: false });
                    {
                        // Quota and rate limit checks are independent.
                        const [_quotaResult, _rateLimitResult] = await Promise.all([
                            TokenUsageService.checkQuota(userId),
                            TokenUsageService.checkRateLimit(userId),
                        ]);
                    }

                    // 2. Sanitize & Prepare Prompt
                    const sanitizedPrompt = this.sanitizePrompt(prompt);

                    // 3. Inject thoughtSignature if present
                    if (options?.thoughtSignature && Array.isArray(sanitizedPrompt) && sanitizedPrompt.length > 0) {
                        const lastContent = sanitizedPrompt[sanitizedPrompt.length - 1]!;
                        if (lastContent.parts.length > 0) {
                            const lastPartIdx = lastContent.parts.length - 1;
                            (lastContent.parts[lastPartIdx] as ContentPart).thoughtSignature = options.thoughtSignature;
                        }
                    }

                    const contents: Content[] = typeof sanitizedPrompt === 'string'
                        ? [{ role: 'user' as const, parts: [{ text: sanitizedPrompt }] }]
                        : sanitizedPrompt as Content[];
                    const backendConfig: Record<string, unknown> = {
                        ...mergedConfig,
                        systemInstruction,
                        tools,
                        toolConfig: options?.toolConfig,
                        safetySettings: options?.safetySettings || STANDARD_SAFETY_SETTINGS
                    };
                    headers = await this.prepareBackendRequestHeaders();
                    costReservationId = await this.reserveAgentStream(userId, modelName, true,
                        estimateAgentStreamCost(contents, systemInstruction, tools, modelName, backendConfig.maxOutputTokens), options);
                    return this.callBackendGenerateContentStream(contents, modelName, backendConfig, costReservationId, headers, internalSignal);
                }, 0, 1000, internalSignal);
            });
            return {
                stream: streamResult.stream,
                response: streamResult.response.finally(cleanupRequestLifecycle),
            };
        } catch (error) {
            cleanupRequestLifecycle();
            if (costReservationId) {
