import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useStore } from '@/core/store';
import { useShallow } from 'zustand/react/shallow';
import {
    Image as ImageIcon,
    FileText,
    Music,
    Video,
    Download,
